DROP VIEW "public"."latest_exercise_element_templates";--> statement-breakpoint
ALTER TABLE "exercise_element_templates" ADD COLUMN "baseCollectionVersion" varchar NOT NULL;--> statement-breakpoint
ALTER TABLE "exercise_element_templates" ADD CONSTRAINT "exercise_element_templates_baseCollectionVersion_exercise_element_sets_versionId_fk" FOREIGN KEY ("baseCollectionVersion") REFERENCES "public"."exercise_element_sets"("versionId") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE VIEW "public"."latest_exercise_element_templates" AS (select "exercise_element_templates"."versionId", "exercise_element_templates"."entityId", "exercise_element_templates"."version", "exercise_element_templates"."stateVersion", "exercise_element_templates"."createdBy", "exercise_element_templates"."createdAt", "exercise_element_templates"."title", "exercise_element_templates"."description", "exercise_element_templates"."content", "exercise_element_templates"."baseCollectionVersion" from "exercise_element_templates" inner join "latest_exercise_element_template_version_numbers" on ("exercise_element_templates"."entityId" = "latest_exercise_element_template_version_numbers"."entityId" and "exercise_element_templates"."version" = "latestversion"));